const response = $input.first().json;

const rawToken =
  response?.access_token ??
  response?.data?.access_token ??
  response?.result?.access_token ??
  response?.token?.access_token ??
  response?.data?.token;

if (!rawToken || !String(rawToken).trim()) {
  throw new Error(
    'Access token tidak ditemukan pada respons Olsera. Field tingkat atas: ' +
    (Object.keys(response ?? {}).join(', ') || '(kosong)') + '.'
  );
}

const accessToken = String(rawToken).trim().replace(/^Bearer\s+/i, '');
if (!accessToken) {
  throw new Error('Access token Olsera kosong setelah normalisasi.');
}

return [{ json: { access_token: accessToken } }];

/*
 * MODE DIAGNOSTIK PERTAMA:
 * Biarkan field definisi omzet kosong, jalankan manual, lalu inspeksi INPUT
 * node berikutnya. Workflow sengaja berhenti sebelum PostgreSQL.
 *
 * MODE PRODUKSI:
 * Isi seluruh field bertanda WAJIB berdasarkan satu respons nyata yang sudah
 * direkonsiliasi dengan laporan Olsera. Jangan menebak nama field.
 */
const CONFIG = {
  LOOKBACK_DAYS: 3,
  MANUAL_BUSINESS_DATE: '',

  REVENUE_FIELD: '',          // WAJIB, path nominal per report row
  RECORD_KEY_FIELDS: [],      // WAJIB, contoh setelah verifikasi: ['order_id', 'item_id']
  ROW_GRAIN: '',              // WAJIB, contoh: 'order-line'
  WUNPAID: '',                // WAJIB: '0' atau '1' setelah uji A/B
  AMOUNT_BASIS: '',           // WAJIB, contoh: 'net-after-discount-before-return'
  SOURCE_SCOPE: 'grandivo-main',
  CALCULATION_VERSION: 'v1',

  PER_PAGE: 15,
  MAX_REQUESTS: 500,
  TIMEZONE: 'Asia/Jakarta',
  SOURCE_ENDPOINT: 'https://api-open.olsera.co.id/api/open-api/v1/en/report/salesdetails',
};

const token = String($input.first().json.access_token ?? '').trim();
if (!token) {
  throw new Error('Access token Olsera kosong sebelum membuat rentang tanggal.');
}

const ymdInTimezone = (date) => {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: CONFIG.TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const values = Object.fromEntries(
    parts
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value])
  );

  return values.year + '-' + values.month + '-' + values.day;
};

const isStrictYmd = (value) => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const parsed = new Date(Date.UTC(year, month - 1, day));

  return (
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day
  );
};

const manualDate = String(CONFIG.MANUAL_BUSINESS_DATE || '').trim();
if (manualDate && !isStrictYmd(manualDate)) {
  throw new Error('MANUAL_BUSINESS_DATE bukan tanggal kalender YYYY-MM-DD yang valid.');
}

const lookbackDays = Number(CONFIG.LOOKBACK_DAYS);
if (!Number.isInteger(lookbackDays) || lookbackDays < 1 || lookbackDays > 31) {
  throw new Error('LOOKBACK_DAYS harus bilangan bulat antara 1 dan 31.');
}

const perPage = Number(CONFIG.PER_PAGE);
if (!Number.isInteger(perPage) || perPage !== 15) {
  throw new Error('PER_PAGE harus 15 sampai batas resmi Olsera diverifikasi.');
}

const maxRequests = Number(CONFIG.MAX_REQUESTS);
if (!Number.isInteger(maxRequests) || maxRequests !== 500) {
  throw new Error('MAX_REQUESTS harus 500 agar sama dengan batas node HTTP.');
}

if (!Array.isArray(CONFIG.RECORD_KEY_FIELDS)) {
  throw new Error('RECORD_KEY_FIELDS harus berupa array.');
}

const todayWib = ymdInTimezone(new Date());
const todayAnchor = new Date(todayWib + 'T12:00:00+07:00');
const dates = manualDate
  ? [manualDate]
  : Array.from({ length: lookbackDays }, (_, index) =>
      ymdInTimezone(new Date(todayAnchor.getTime() - (index + 1) * 86400000))
    );

const sourceFetchedAt = new Date().toISOString();

return dates.map((businessDate) => ({
  json: {
    access_token: token,
    business_date: businessDate,
    revenue_field: String(CONFIG.REVENUE_FIELD || '').trim(),
    record_key_fields: CONFIG.RECORD_KEY_FIELDS.map((field) => String(field).trim()),
    row_grain: String(CONFIG.ROW_GRAIN || '').trim(),
    wunpaid: String(CONFIG.WUNPAID || '').trim(),
    amount_basis: String(CONFIG.AMOUNT_BASIS || '').trim(),
    source_scope: String(CONFIG.SOURCE_SCOPE || '').trim(),
    calculation_version: String(CONFIG.CALCULATION_VERSION || '').trim(),
    per_page: perPage,
    max_requests: maxRequests,
    timezone: CONFIG.TIMEZONE,
    source_endpoint: CONFIG.SOURCE_ENDPOINT,
    source_fetched_at: sourceFetchedAt,
  },
}));

