={{ (() => {
  const body = $response.body;
  const candidates = [
    body?.data?.data,
    body?.data?.items,
    body?.data?.rows,
    body?.result?.data,
    body?.result?.items,
    body?.result?.rows,
    body?.data,
    body?.items,
    body?.rows,
    body?.result,
    body,
  ];
  const rows = candidates.find((candidate) => Array.isArray(candidate));
  if (!rows) return true;

  const meta = body?.meta ?? body?.data?.meta ?? body?.result?.meta ?? {};
  const current = Number(
    meta?.current_page ??
    body?.current_page ??
    body?.data?.current_page ??
    body?.result?.current_page ??
    0
  );
  const last = Number(
    meta?.last_page ??
    body?.last_page ??
    body?.data?.last_page ??
    body?.result?.last_page ??
    0
  );
  const links = body?.links ?? body?.data?.links ?? body?.result?.links;
  if (Number.isInteger(current) && current > 0 &&
      Number.isInteger(last) && last > 0) {
    return current >= last;
  }
  if (links && Object.hasOwn(links, 'next')) {
    return links.next == null;
  }

  const nextOwners = [body, body?.data, body?.result];
  for (const owner of nextOwners) {
    if (owner && Object.hasOwn(owner, 'next_page_url')) {
      return owner.next_page_url == null;
    }
  }

  return rows.length < 15;
})() }}

