const responseItems = $input.all();
const windows = $('Tanggal Bisnis WIB & Konfigurasi').all();

const AUTO_REVENUE_CANDIDATES = [
  'net_sales',
  'sales_net',
  'net_total',
  'total_net',
  'grand_total',
  'total_amount',
  'sales_total',
  'total_sales',
  'amount',
  'total',
  'payment_amount',
  'paid_amount',
];

const AUTO_KEY_CANDIDATES = [
  'id',
  'detail_id',
  'sales_detail_id',
  'order_detail_id',
  'order_item_id',
  'item_id',
  'transaction_id',
  'sales_id',
  'order_id',
  'invoice_id',
  'order_no',
  'invoice_no',
];

const readPath = (object, path) =>
  String(path)
    .split('.')
    .filter(Boolean)
    .reduce((value, key) => (value == null ? undefined : value[key]), object);

const firstDefined = (object, paths) => {
  for (const path of paths) {
    const value = readPath(object, path);
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return undefined;
};

const toText = (value) =>
  value === undefined || value === null ? '' : String(value).trim();

const boundedText = (value, label, maxLength = 512) => {
  const text = toText(value);
  if (text.length > maxLength) {
    throw new Error(label + ' melebihi ' + maxLength + ' karakter.');
  }
  return text;
};

const normalizeDecimal = (value, label) => {
  let raw;

  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value)) {
      throw new Error(
        label + ' berupa JSON number pecahan/tidak aman. ' +
        'Nominal pecahan wajib berupa string desimal agar presisinya utuh.'
      );
    }
    raw = String(value);
  } else if (typeof value === 'string') {
    raw = value.trim();
  } else {
    throw new Error(label + ' harus berupa JSON number atau string desimal.');
  }

  const match = /^-?(\d+)(?:\.(\d+))?$/.exec(raw);
  if (!match) {
    throw new Error(
      label + ' harus desimal kanonik tanpa pemisah ribuan/mata uang: ' + raw
    );
  }

  if (match[1].length > 20 || (match[2] ?? '').length > 8 || raw.length > 64) {
    throw new Error(label + ' melebihi batas presisi yang diizinkan.');
  }

  return raw;
};

const extractRows = (page) => {
  const candidates = [
    page?.data?.data,
    page?.data?.items,
    page?.data?.rows,
    page?.result?.data,
    page?.result?.items,
    page?.result?.rows,
    page?.data,
    page?.items,
    page?.rows,
    page?.result,
    page,
  ];

  return candidates.find((candidate) => Array.isArray(candidate));
};

const paginationInfo = (page) => {
  const meta = page?.meta ?? page?.data?.meta ?? page?.result?.meta ?? {};
  const links = page?.links ?? page?.data?.links ?? page?.result?.links;
  const nextOwners = [page, page?.data, page?.result];
  let hasExplicitNext = false;
  let next = null;

  if (links && Object.hasOwn(links, 'next')) {
    hasExplicitNext = true;
    next = links.next;
  } else {
    for (const owner of nextOwners) {
      if (owner && Object.hasOwn(owner, 'next_page_url')) {
        hasExplicitNext = true;
        next = owner.next_page_url;
        break;
      }
    }
  }

  const toPositiveInteger = (value) => {
    const number = Number(value);
    return Number.isInteger(number) && number > 0 ? number : 0;
  };

  const toNonnegativeInteger = (value) => {
    const number = Number(value);
    return Number.isInteger(number) && number >= 0 ? number : null;
  };

  return {
    current: toPositiveInteger(
      meta?.current_page ??
      page?.current_page ??
      page?.data?.current_page ??
      page?.result?.current_page
    ),
    last: toPositiveInteger(
      meta?.last_page ??
      page?.last_page ??
      page?.data?.last_page ??
      page?.result?.last_page
    ),
    perPage: toPositiveInteger(
      meta?.per_page ??
      page?.per_page ??
      page?.data?.per_page ??
      page?.result?.per_page
    ),
    total: toNonnegativeInteger(
      meta?.total ??
      page?.total ??
      page?.data?.total ??
      page?.result?.total
    ),
    hasExplicitNext,
    next,
    meta,
    links: links ?? null,
  };
};

const isMeaningfulError = (value) =>
  value !== undefined && value !== null && value !== false &&
  value !== 0 && value !== '';

const assertSuccessfulEnvelope = (page, businessDate) => {
  if (page == null || (typeof page !== 'object' && !Array.isArray(page))) {
    throw new Error('Body Olsera bukan JSON object/array untuk ' + businessDate + '.');
  }

  if (!Array.isArray(page) && isMeaningfulError(page.error)) {
    throw new Error(
      'Olsera mengembalikan error untuk ' + businessDate + ': ' +
      JSON.stringify(page.error)
    );
  }

  if (!Array.isArray(page) && page.success === false) {
    throw new Error('Olsera menandai respons gagal untuk ' + businessDate + '.');
  }

  if (!Array.isArray(page) && page.status === false) {
    throw new Error('Status Olsera false untuk ' + businessDate + '.');
  }

  if (!Array.isArray(page) && page.status !== undefined && page.status !== null) {
    const statusText = String(page.status).trim().toLowerCase();
    if (/^\d+$/.test(statusText)) {
      const statusCode = Number(statusText);
      if (statusCode < 200 || statusCode >= 300) {
        throw new Error('Status Olsera ' + statusText + ' untuk ' + businessDate + '.');
      }
    } else if (['error', 'failed', 'failure', 'unauthorized', 'false'].includes(statusText)) {
      throw new Error('Status Olsera gagal (' + statusText + ') untuk ' + businessDate + '.');
    }
  }
};

const pairedIndex = (item) => {
  if (Array.isArray(item.pairedItem) && item.pairedItem.length !== 1) {
    throw new Error('Satu halaman harus tertaut tepat ke satu tanggal bisnis.');
  }

  const paired = Array.isArray(item.pairedItem)
    ? item.pairedItem[0]
    : item.pairedItem;
  const index = Number(paired?.item);

  if (!Number.isInteger(index) || index < 0 || index >= windows.length) {
    throw new Error('Item linking pagination n8n tidak valid; database tidak ditulis.');
  }

  return index;
};

const pagesByWindow = new Map();
for (const item of responseItems) {
  const statusCode = Number(item.json?.statusCode);
  if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) {
    throw new Error('HTTP status Sales details tidak valid: ' + String(item.json?.statusCode));
  }

  if (!Object.hasOwn(item.json ?? {}, 'body')) {
    throw new Error('Full response HTTP tidak memiliki body; database tidak ditulis.');
  }

  const index = pairedIndex(item);
  if (!pagesByWindow.has(index)) pagesByWindow.set(index, []);
  pagesByWindow.get(index).push({
    statusCode,
    body: item.json.body,
  });
}

const output = [];

for (let windowIndex = 0; windowIndex < windows.length; windowIndex++) {
  const config = windows[windowIndex].json;
  const responses = pagesByWindow.get(windowIndex) ?? [];

  if (responses.length === 0) {
    throw new Error('Tidak ada respons Olsera untuk ' + config.business_date + '.');
  }

  if (responses.length > Number(config.max_requests)) {
    throw new Error('Jumlah halaman melebihi MAX_REQUESTS untuk ' + config.business_date + '.');
  }

  const pages = [];
  const rows = [];
  const pageInfos = [];

  for (let pageIndex = 0; pageIndex < responses.length; pageIndex++) {
    const page = responses[pageIndex].body;
    assertSuccessfulEnvelope(page, config.business_date);

    const pageRows = extractRows(page);
    if (!Array.isArray(pageRows)) {
      throw new Error(
        'Wrapper Sales details belum dikenali untuk ' + config.business_date +
        '. Field tingkat atas: ' +
        (Array.isArray(page) ? '(top-level array)' : Object.keys(page ?? {}).join(', ')) +
        '.'
      );
    }

    for (let rowIndex = 0; rowIndex < pageRows.length; rowIndex++) {
      const row = pageRows[rowIndex];
      if (!row || typeof row !== 'object' || Array.isArray(row)) {
        throw new Error(
          'Baris non-object pada halaman ' + (pageIndex + 1) +
          ', indeks ' + rowIndex + ' untuk ' + config.business_date + '.'
        );
      }
      rows.push(row);
    }

    pages.push(page);
    pageInfos.push(paginationInfo(page));
  }

  const finalInfo = pageInfos[pageInfos.length - 1];
  const finalByMeta =
    finalInfo.current > 0 &&
    finalInfo.last > 0 &&
    finalInfo.current >= finalInfo.last;
  const finalByLink =
    finalInfo.hasExplicitNext &&
    finalInfo.next == null;

  if (!finalByMeta && !finalByLink) {
    throw new Error(
      'Pagination Sales details tidak dapat dibuktikan lengkap untuk ' +
      config.business_date + '. Respons wajib memiliki meta current/last ' +
      'atau link next yang eksplisit.'
    );
  }

  for (let pageIndex = 0; pageIndex < pageInfos.length; pageIndex++) {
    const info = pageInfos[pageIndex];
    if (info.current > 0 && info.current !== pageIndex + 1) {
      throw new Error(
        'Urutan halaman tidak konsisten untuk ' + config.business_date +
        ': menerima ' + info.current + ' pada posisi ' + (pageIndex + 1) + '.'
      );
    }
    if (info.last > 0 && finalInfo.last > 0 && info.last !== finalInfo.last) {
      throw new Error('last_page berubah di tengah pagination untuk ' + config.business_date + '.');
    }
    if (
      info.perPage > 0 &&
      info.perPage !== Number(config.per_page) &&
      pageIndex < pageInfos.length - 1
    ) {
      throw new Error(
        'Olsera memakai per_page=' + info.perPage +
        ', bukan ' + config.per_page + '; konfigurasi harus diverifikasi.'
      );
    }
  }

  const totals = pageInfos
    .map((info) => info.total)
    .filter((total) => total !== null);
  if (totals.length > 0) {
    if (new Set(totals).size !== 1 || totals[0] !== rows.length) {
      throw new Error(
        'Jumlah baris tidak cocok dengan meta.total untuk ' + config.business_date +
        ': baris ' + rows.length + ', total ' + totals.join(', ') + '.'
      );
    }
  }

  if (
    responses.length >= Number(config.max_requests) &&
    !finalByMeta &&
    !finalByLink
  ) {
    throw new Error('Batas pagination tercapai tanpa bukti halaman akhir.');
  }

  const missingConfig = [];
  const revenueField = toText(config.revenue_field);
  const recordKeyFields = Array.isArray(config.record_key_fields)
    ? config.record_key_fields.map(toText).filter(Boolean)
    : [];
  const rowGrain = toText(config.row_grain);
  const wunpaid = toText(config.wunpaid);
  const amountBasis = toText(config.amount_basis);
  const sourceScope = toText(config.source_scope);
  const calculationVersion = toText(config.calculation_version);

  if (!revenueField) missingConfig.push('REVENUE_FIELD');
  if (recordKeyFields.length === 0) missingConfig.push('RECORD_KEY_FIELDS');
  if (!rowGrain) missingConfig.push('ROW_GRAIN');
  if (!['0', '1'].includes(wunpaid)) missingConfig.push('WUNPAID');
  if (!amountBasis) missingConfig.push('AMOUNT_BASIS');
  if (!sourceScope) missingConfig.push('SOURCE_SCOPE');
  if (!calculationVersion) missingConfig.push('CALCULATION_VERSION');

  if (missingConfig.length > 0) {
    const revenueSuggestions = rows.length === 0
      ? []
      : AUTO_REVENUE_CANDIDATES.filter((path) =>
          rows.every((row) => {
            const value = readPath(row, path);
            if (value === undefined || value === null || String(value).trim() === '') {
              return false;
            }
            try {
              normalizeDecimal(value, path);
              return true;
            } catch {
              return false;
            }
          })
        );

    const keySuggestions = rows.length === 0
      ? []
      : AUTO_KEY_CANDIDATES.filter((path) =>
          rows.every((row) => {
            const value = readPath(row, path);
            return (
              value !== undefined &&
              value !== null &&
              typeof value !== 'object' &&
              String(value).trim() !== ''
            );
          })
        );

    throw new Error(
      'Konfigurasi produksi belum lengkap: ' + missingConfig.join(', ') + '. ' +
      'Inspeksi INPUT node ini dan rekonsiliasi dengan laporan Olsera. ' +
      'Kandidat nominal (diagnostik saja): ' +
      (revenueSuggestions.join(', ') || '(tidak ada)').toString() + '. ' +
      'Kandidat kunci (diagnostik saja): ' +
      (keySuggestions.join(', ') || '(tidak ada)').toString() + '.'
    );
  }

  const normalizedByKey = new Map();

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];
    const rawAmount = readPath(row, revenueField);
    if (rawAmount === undefined || rawAmount === null || String(rawAmount).trim() === '') {
      throw new Error(
        'REVENUE_FIELD ' + revenueField + ' kosong pada baris ' + rowIndex +
        ' untuk ' + config.business_date + '.'
      );
    }

    const revenueAmount = normalizeDecimal(
      rawAmount,
      'Nominal baris ' + rowIndex + ' (' + revenueField + ')'
    );

    const keyParts = recordKeyFields.map((path) => {
      const value = readPath(row, path);
      if (
        value === undefined ||
        value === null ||
        typeof value === 'object' ||
        String(value).trim() === ''
      ) {
        throw new Error(
          'RECORD_KEY_FIELDS path ' + path + ' tidak scalar/non-kosong pada baris ' +
          rowIndex + ' untuk ' + config.business_date + '.'
        );
      }
      return [path, String(value).trim()];
    });

    const recordKey = keyParts
      .map(([path, value]) => path + '=' + encodeURIComponent(value))
      .join('|');

    if (recordKey.length === 0 || recordKey.length > 240) {
      throw new Error(
        'Record key kosong/terlalu panjang pada baris ' + rowIndex +
        ' untuk ' + config.business_date + '.'
      );
    }

    if (normalizedByKey.has(recordKey)) {
      throw new Error(
        'Record key ganda pada ' + config.business_date + ': ' + recordKey +
        '. Tambahkan field pembeda yang stabil; tidak ada baris yang dihapus diam-diam.'
      );
    }

    normalizedByKey.set(recordKey, {
      record_key: recordKey,
      order_id: boundedText(
        firstDefined(row, ['order_id', 'sales_id', 'transaction_id', 'id']),
        'order_id'
      ),
      order_no: boundedText(
        firstDefined(row, ['order_no', 'invoice_no', 'receipt_no', 'sales_no', 'code']),
        'order_no'
      ),
      source_timestamp_raw: boundedText(
        firstDefined(row, [
          'order_date',
          'transaction_date',
          'trans_date',
          'sales_date',
          'closed_at',
          'created_at',
          'date',
        ]),
        'source_timestamp_raw',
        128
      ),
      status: boundedText(
        firstDefined(row, ['status', 'order_status', 'sales_status']),
        'status',
        128
      ),
      payment_status: boundedText(
        firstDefined(row, ['payment_status', 'is_paid', 'paid_status', 'paid']),
        'payment_status',
        128
      ),
      customer_id: boundedText(
        firstDefined(row, ['customer_id', 'customer.id']),
        'customer_id'
      ),
      store_id: boundedText(
        firstDefined(row, ['store_id', 'outlet_id', 'store.id', 'outlet.id']),
        'store_id'
      ),
      revenue_amount: revenueAmount,
      raw_payload: row,
    });
  }

  const normalizedRows = [...normalizedByKey.values()];
  const sourceMetadata = pageInfos.map((info, pageIndex) => {
    const page = pages[pageIndex];
    const status = Array.isArray(page) ? null : page?.status ?? null;
    return {
      page_index: pageIndex + 1,
      http_status_code: responses[pageIndex].statusCode,
      current_page: info.current || null,
      last_page: info.last || null,
      per_page: info.perPage || null,
      total: info.total,
      next: info.hasExplicitNext ? info.next : null,
      has_explicit_next: info.hasExplicitNext,
      response_status:
        status === null || typeof status === 'object' ? null : String(status),
    };
  });

  output.push({
    json: {
      source_scope: sourceScope,
      business_date: config.business_date,
      report_row_count: normalizedRows.length,
      page_count: pages.length,
      revenue_field: revenueField,
      record_key_fields_json: JSON.stringify(recordKeyFields),
      row_grain: rowGrain,
      wunpaid,
      amount_basis: amountBasis,
      calculation_version: calculationVersion,
      source_endpoint: config.source_endpoint,
      source_fetched_at: config.source_fetched_at,
      rows_json: JSON.stringify(normalizedRows),
      source_metadata_json: JSON.stringify(sourceMetadata),
    },
  });
}

return output;

const results = $input.all().map((item) => {
  const raw = item.json.result;
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw === 'string') {
    try {
      return JSON.parse(raw);
    } catch {
      throw new Error('Hasil PostgreSQL bukan JSON yang valid: ' + raw);
    }
  }
  throw new Error('PostgreSQL tidak mengembalikan hasil sinkronisasi.');
});

const uniqueDates = new Set(
  results.map((result) => String(result.source_scope) + '|' + String(result.business_date))
);
if (uniqueDates.size !== results.length) {
  throw new Error('PostgreSQL mengembalikan scope/tanggal duplikat.');
}

results.sort((left, right) =>
  String(left.business_date).localeCompare(String(right.business_date))
);

return [{
  json: {
    status: 'SUCCESS',
    message:
      'Snapshot Sales details tersimpan/ditangani untuk ' +
      results.length + ' tanggal bisnis.',
    dates_processed: results.length,
    results,
    synced_at_wib: new Date().toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta',
    }),
  },
}];
